css='''@font-face{font-family:Inter;src:local("Inter")}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#080e1b;color:#e8f0fb;font:16px/1.65 Inter,system-ui,sans-serif}a{color:inherit;text-decoration:none}a:hover{color:#63d8ed}button,input,select,textarea{font:inherit}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(3rem,8vw,7rem);line-height:1.02;letter-spacing:-.065em}h2{font-size:clamp(2rem,4vw,3.8rem);line-height:1.12;letter-spacing:-.045em}h3{font-size:1.3rem}p{color:#a8b6cb}small,.eyebrow{color:#65d5e9;letter-spacing:.16em;text-transform:uppercase;font-size:.75rem;font-weight:700}.wrap{max-width:1200px;margin:auto;padding:0 24px}header{position:sticky;top:0;z-index:5;background:#080e1be8;backdrop-filter:blur(16px);border-bottom:1px solid #ffffff15}.nav{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{font-weight:800;letter-spacing:.12em;white-space:nowrap}.brand b{display:inline-grid;place-items:center;width:38px;height:38px;border:1px solid #60d8ed;margin-right:10px;color:#79deef}nav{display:flex;gap:26px;flex-wrap:wrap}nav a{font-size:.87rem;color:#c2cee0}.cta,.button{display:inline-block;border:1px solid #6ce0ef;background:#73dbe9;color:#061421;padding:12px 20px;font-weight:700;cursor:pointer}.button.secondary{color:#e9f3ff;background:transparent;border-color:#61748d}.button:hover,.cta:hover{background:#a2edfa;color:#05101e}.hero{position:relative;min-height:690px;display:flex;align-items:center;overflow:hidden;background:radial-gradient(circle at 75% 34%,#0b5263 0,#13284a 24%,transparent 52%),linear-gradient(145deg,#080d19,#101d34)}.hero:before{content:'';position:absolute;inset:0;background-image:linear-gradient(#77d9ed10 1px,transparent 1px),linear-gradient(90deg,#77d9ed10 1px,transparent 1px);background-size:64px 64px;mask-image:linear-gradient(to right,transparent,#000)}.hero .wrap{position:relative;width:100%}.hero p{max-width:590px;font-size:1.2rem}.hero h1 span{color:#75dded}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}.section{padding:100px 0;border-top:1px solid #ffffff13}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:30px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{border:1px solid #ffffff20;background:#111d31;padding:26px;min-width:0}.card:hover{border-color:#74dceb66}.card .art{height:230px;margin:-26px -26px 22px;display:grid;place-items:center;background:radial-gradient(circle at 60% 40%,#267b92,#162b4c 46%,#0d1729);color:#9ce6f2;font-size:4rem;font-weight:800;letter-spacing:-.12em}.card p{margin-bottom:0}.cols{display:grid;grid-template-columns:1fr 1fr;gap:50px}.strip{display:flex;flex-wrap:wrap;gap:12px}.chip{border:1px solid #ffffff2c;padding:9px 14px;color:#cbd8e9}.steps{counter-reset:step}.steps .card:before{counter-increment:step;content:counter(step,decimal-leading-zero);display:block;color:#65d5e9;margin-bottom:25px;font-size:1.4rem}footer{padding:50px 0;border-top:1px solid #ffffff25}.footer{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.intro{padding:110px 0 75px;background:radial-gradient(circle at 90% 0,#153852,transparent 45%)}.intro h1{font-size:clamp(2.8rem,6vw,5rem);max-width:850px}.intro p{max-width:700px;font-size:1.1rem}.detail{padding:70px 0}.detail-grid{display:grid;grid-template-columns:1fr 2fr;gap:35px;border-top:1px solid #ffffff25;padding:26px 0}.detail-grid h2{font-size:1.4rem}.placeholder{aspect-ratio:16/9;display:grid;place-items:center;background:linear-gradient(145deg,#162645,#134359,#0b1425);border:1px solid #ffffff2b;color:#8bddec;text-align:center;padding:20px}.form{display:grid;grid-template-columns:1fr 1fr;gap:18px;max-width:850px}.field{display:grid;gap:5px}.field.wide{grid-column:1/-1}input,select,textarea{background:#101d30;border:1px solid #607088;color:white;padding:12px;width:100%;border-radius:0}textarea{min-height:150px}input:focus,select:focus,textarea:focus{outline:2px solid #66d6e7}label{font-weight:600}a:focus-visible,button:focus-visible{outline:2px solid #8decfa;outline-offset:3px}.media,.project-video{width:100%;aspect-ratio:16/9;background:#13243b}.skip{position:absolute;left:-9999px}.skip:focus{left:10px;top:10px;z-index:10;background:white;color:black;padding:8px}@media(max-width:800px){.grid,.cols{grid-template-columns:1fr 1fr}.nav{align-items:flex-start;padding-top:16px;padding-bottom:16px;flex-wrap:wrap}nav{order:3;width:100%;gap:15px}.nav .cta{display:none}.hero{min-height:600px}}@media(max-width:600px){.grid,.cols,.form{grid-template-columns:1fr}.section{padding:65px 0}.hero{min-height:550px}.field.wide{grid-column:auto}.section-head{display:block}.card .art{height:180px}}@media(prefers-reduced-motion:no-preference){.hero:before{animation:drift 25s linear infinite}@keyframes drift{to{background-position:64px 64px}}}'''
(root/'style.css').write_text(css)
nav=''.join(f'<a href="/{p}/">{p.title()}</a>' for p in ['work','services','about','process','contact'])
headnav=f'<a class="skip" href="#main">Skip to content</a><header><div class="wrap nav"><a href="/" class="brand"><b>AW</b> ANZA WORKS</a><nav aria-label="Main navigation"><a href="/">Home</a>{nav}</nav><a class="cta" href="/contact/">Start a Project</a></div></header>'
foot='<footer><div class="wrap footer"><div><strong>ANZA WORKS</strong><p>Independent digital product and software studio.</p></div><div><a href="/work/">Work</a> · <a href="/services/">Services</a> · <a href="/contact/">Contact</a><p>© 2026 Anza Works</p></div></div></footer>'
def write(path,title,desc,body):
 path.parent.mkdir(parents=True,exist_ok=True)
 depth=len(path.relative_to(root).parts)-1
 relative='../'*depth
 canonical='https://anzaworks.lk'+('/' if path==root/'index.html' else '/'+str(path.parent.relative_to(root)).replace('\\','/')+'/')
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Anza Works</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)} | Anza Works"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta name="twitter:card" content="summary"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/manifest.webmanifest"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'ProfessionalService','name':'Anza Works','url':'https://anzaworks.lk'})}</script></head><body>{headnav}<main id="main">{body}</main>{foot}</body></html>'''
 path.write_text(html)
def cards(items):return '<div class="grid">'+''.join(items)+'</div>'
def projcard(p):return f'<a class="card" href="/work/{p[0]}/"><div class="art" aria-hidden="true">{escape(p[1][0])}</div><small>{escape(p[2])} · Concept</small><h3>{escape(p[1])}</h3><p>{escape(p[3])}</p></a>'
sec=lambda name,body:f'<section class="section"><div class="wrap"><h2>{name}</h2>{body}</div></section>'
home='<section class="hero"><div class="wrap"><small>Independent digital studio</small><h1>Digital experiences<br><span>built differently.</span></h1><p>Anza Works designs and builds websites, software, and digital systems that help businesses move forward.</p><div class="actions"><a class="button" href="/work/">View My Work</a><a class="button secondary" href="/contact/">Start a Project</a></div></div></section>'
home+=sec('Selected work',cards(map(projcard,projects[:3]))+'<p><a href="/work/">Explore all work →</a></p>')
home+=sec('A studio built around useful work','<div class="cols"><p>From the first conversation to ongoing support, I bring design and development together to make digital tools that are clear, dependable, and distinct.</p><p>Every project starts with understanding the people using it and the business it serves.</p></div>')
home+=sec('What I build',cards(f'<a class="card" href="/services/"><small>Service</small><h3>{escape(s[0])}</h3><p>{escape(s[1])}</p></a>' for s in services[:6]))
home+=sec('Why Anza Works',cards(f'<div class="card"><h3>{x}</h3><p>{y}</p></div>' for x,y in [('Design with purpose','The interface and the business goal should reinforce each other.'),('Built for real use','Clear workflows, responsive layouts, and accessible foundations.'),('Room to grow','Maintainable systems that can evolve with your needs.')]))
home+=sec('From idea to launch','<div class="grid steps">'+''.join(f'<div class="card"><h3>{x}</h3><p>{y}</p></div>' for x,y in [('Discover','Understand the problem.'),('Design','Shape the experience.'),('Build','Develop and test.'),('Support','Improve after launch.')])+'</div>')
home+=sec('Selected technologies','<div class="strip">'+''.join(f'<span class="chip">{x}</span>' for x in ['React','TypeScript','Next.js','Accessible HTML','CSS','APIs','PostgreSQL'])+'</div>')
home+=sec('Client voices','<p>Testimonials will appear here when approved client feedback is available.</p>')
home+=sec('Have a project in mind?','<p>Tell me what you are building and where you need help.</p><a class="button" href="/contact/">Start a Project</a>')
write(root/'index.html','Digital product and web studio','Anza Works builds websites, software and digital systems for businesses.',home)
write(root/'work/index.html','Selected work','Explore website, commerce and software concepts by Anza Works.','<section class="intro"><div class="wrap"><small>Portfolio</small><h1>Work with purpose.</h1><p>Selected concepts demonstrating the kind of experiences Anza Works can build. These are examples, not commissioned client projects.</p></div></section>'+sec('Explore projects',cards(map(projcard,projects))))
for i,p in enumerate(projects):
 slug,name,kind,short,full,challenge,solution,features,tech=p
 nextp=projects[(i+1)%len(projects)]
 body=f'<section class="intro"><div class="wrap"><small>{escape(kind)} · Concept case study</small><h1>{escape(name)}</h1><p>{escape(short)}</p></div></section><div class="wrap detail"><div class="placeholder" role="img" aria-label="Concept artwork placeholder for {escape(name)}"><div><strong>{escape(name)}</strong><br>Project imagery coming soon</div></div>'
 for h,content in [('Overview',full),('Challenge',challenge),('Solution',solution),('Design','The visual direction is designed to support the content and key tasks. Final design assets will be added when the project is developed.'),('Technology',', '.join(tech)),('Results','This concept has no measured client results. Outcomes will be added only when they can be verified.')]:body+=f'<section class="detail-grid"><h2>{h}</h2><p>{escape(content)}</p></section>'
 body+='<section class="detail-grid"><h2>Key features</h2><ul>'+''.join(f'<li>{escape(f)}</li>' for f in features)+'</ul></section>'
 asset=media.get(slug)
 if asset:
  sources=''.join(f'<source data-src="{escape(asset[k],quote=True)}" type="video/{k}">' for k in ('mp4','webm') if asset.get(k))
  poster=f' poster="{escape(asset["poster"],quote=True)}"' if asset.get('poster') else ''
  body+=f'<section class="detail-grid"><h2>Project video</h2><div><video class="project-video" controls playsinline preload="none"{poster} aria-label="{escape(name)} project video">{sources}Your browser does not support video.</video><p>Press play to load the video.</p></div></section><script src="/project-media.js" defer></script>'
 else:body+='<section class="detail-grid"><h2>Screenshots & video</h2><p>Media can be added when approved assets are available.</p></section>'
 body+=f'<section class="detail-grid"><h2>Next project</h2><p><a href="/work/{nextp[0]}/">{escape(nextp[1])} →</a></p></section><a class="button" href="/contact/">Discuss a project</a></div>'
 write(root/f'work/{slug}/index.html',name,short,body)
write(root/'services/index.html','Services','Website design, business software, commerce, dashboards and support.','<section class="intro"><div class="wrap"><small>Services</small><h1>Practical digital work, made distinctive.</h1><p>Choose a focused website or a more involved product engagement.</p></div></section>'+sec('Ways to work together',cards(f'<article class="card"><small>For {escape(s[2])}</small><h3>{escape(s[0])}</h3><p>{escape(s[1])}</p><p><strong>Common features:</strong> {escape(s[3])}</p><a href="/contact/">Enquire about this service →</a></article>' for s in services)))
write(root/'about/index.html','About','The approach and working style behind Anza Works.','<section class="intro"><div class="wrap"><small>About</small><h1>Independent by design.</h1><p>Anza Works is an independent studio for businesses that value both a strong first impression and solid underlying systems.</p></div></section>'+''.join(sec(h,f'<p>{p}</p>') for h,p in [('My approach','Understand the business context, define the essential task, then design and build around it.'),('What I build','Websites, digital products, and operational software tailored to real workflows.'),('How I work','A clear scope, iterative review, and direct communication throughout.'),('Technology','Choose tools for the problem, with maintainability, performance, and accessibility in mind.'),('Continuous support','After launch, continue improving what matters as needs change.')]))
steps=['Discovery','Requirements','Proposal / Quote','Design','Development','Review','Launch','Support']
write(root/'process/index.html','Process','A clear path from discovery to launch and support.','<section class="intro"><div class="wrap"><small>Process</small><h1>Clear steps. Better outcomes.</h1><p>A structured process keeps decisions visible and the work moving.</p></div></section>'+sec('The journey','<div class="grid steps">'+''.join(f'<div class="card"><h3>{x}</h3><p>{y}</p></div>' for x,y in zip(steps,['Explore goals and constraints.','Map users, content and functionality.','Agree scope and commercial terms.','Create and review the interface.','Build the product in working stages.','Test and refine together.','Prepare and release the finished work.','Maintain and evolve the product.']))+'</div>'))
contact='''<section class="intro"><div class="wrap"><small>Contact</small><h1>Let’s make something useful.</h1><p>Share a few details and your email app will open a draft enquiry. Nothing is stored on this site.</p></div></section><section class="section"><div class="wrap"><form id="enquiry" class="form"><div class="field"><label for="name">Name *</label><input id="name" name="name" required maxlength="100"></div><div class="field"><label for="business">Business name</label><input id="business" name="business" maxlength="120"></div><div class="field"><label for="email">Email *</label><input id="email" name="email" type="email" required></div><div class="field"><label for="phone">Phone / WhatsApp</label><input id="phone" name="phone" type="tel"></div><div class="field"><label for="type">Project type *</label><select id="type" name="type" required><option value="">Select a type</option><option>Website</option><option>Online shop</option><option>Software / app</option><option>Other</option></select></div><div class="field"><label for="budget">Budget range</label><select id="budget" name="budget"><option value="">Prefer to discuss</option><option>Under LKR 250,000</option><option>LKR 250,000–500,000</option><option>LKR 500,000–1,000,000</option><option>Over LKR 1,000,000</option></select></div><div class="field"><label for="date">Target launch date</label><input id="date" name="date" type="date"></div><div class="field wide"><label for="description">Project description *</label><textarea id="description" name="description" required minlength="15"></textarea></div><div class="field wide"><button class="button" type="submit">Open email draft</button><p id="form-status" role="status"></p></div></form></div></section><script src="/contact.js" defer></script>'''
write(root/'contact/index.html','Contact','Start a project enquiry with Anza Works.',contact)
(root/'contact.js').write_text('''document.querySelector('#enquiry').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const d=new FormData(f);const lines=[...d].map(([k,v])=>`${k}: ${v||'—'}`).join('\\n');const url=`mailto:hello@anzaworks.lk?subject=${encodeURIComponent('Project enquiry — '+d.get('name'))}&body=${encodeURIComponent(lines)}`;document.querySelector('#form-status').textContent='Your email app should open with a draft. Please check the destination address before sending.';location.href=url;});''')
(root/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://anzaworks.lk/sitemap.xml\n')
