(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://anzaworks.lk{u}</loc></url>' for u in urls)+'</urlset>')
(root/'manifest.webmanifest').write_text(json.dumps({'name':'Anza Works','short_name':'Anza','start_url':'/','display':'standalone','theme_color':'#080e1b','background_color':'#080e1b','icons':[{'src':'/favicon.svg','sizes':'any','type':'image/svg+xml'}]}))
(root/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#080e1b"/><text x="6" y="43" fill="#75dded" font-size="29" font-family="sans-serif" font-weight="bold">AW</text></svg>')
(root/'404.html').write_text('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/style.css"><title>Page not found | Anza Works</title></head><body><main class="wrap intro"><h1>Page not found.</h1><p>The page you requested is not here.</p><a class="button" href="/">Return home</a></main></body></html>')
